// TouchLines free-play harness for TimePitch (local evaluation only).
// SYNTHETIC OUTPUT: player and ball movement are generated by the TouchLines engine
// (commit 5c5c71a8a2fb9a02591445cf9114229a4b218253, AGPL-3.0-or-later). They are not
// historical tracking data. Player attributes mapped from the TimePitch catalogue are
// synthetic estimates.
//
// Usage (bundle): node freeplay.mjs --lineup <lineup.json> --out <replay.json> [--ticks 600] [--seed 42]
//                 node freeplay.mjs --upstream-example --out <replay.json>
import { SEED, randomCallCount, seededRandom } from './seed';
import { createMatchState, tickState, getBallPos } from '@/GameEngine/Domain/gameState';
import { gameBus } from '@/GameEngine/Infrastructure/EventBus';
import { PITCH_LENGTH, PITCH_WIDTH } from '@/GameEngine/Domain/pitch';
import type { Formation, GameState } from '@/GameEngine/types';
import type { RosterPlayer, PlayerStatsRecord } from '@/types/playerTypes';
import f442 from '@/Data/formations/4-4-2.json';
import f433 from '@/Data/formations/4-3-3.json';
import f352 from '@/Data/formations/3-5-2.json';
import f451 from '@/Data/formations/4-5-1.json';
import exampleHome from '@/Data/squads/premier_league/49.json';
import exampleAway from '@/Data/squads/premier_league/51.json';
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const UPSTREAM_COMMIT = '5c5c71a8a2fb9a02591445cf9114229a4b218253';
const ENGINE_VERSION = 'touchlines-5c5c71a-freeplay';
const DT = 0.1;
const WALL_LIMIT_MS = 10 * 60 * 1000;
const RSS_LIMIT = 1024 * 1024 * 1024;
const FORMATIONS: Record<string, Formation> = {
  '4-4-2': f442 as Formation, '4-3-3': f433 as Formation, '3-5-2': f352 as Formation, '4-5-1': f451 as Formation,
};

// ── CLI ─────────────────────────────────────────────────────────────────────
function arg(name: string): string | undefined {
  const i = process.argv.indexOf(name);
  return i >= 0 ? process.argv[i + 1] : undefined;
}
const flag = (name: string) => process.argv.includes(name);
// --physical-clock: full match with real halves (testMode off). Requires the "fair" bundle built with
// rolldown.fair.config.mjs, which neutralises upstream TIME_SCALE (18 -> 1) at bundle time without editing
// upstream files; the harness verifies the scale empirically after the first tick and aborts otherwise.
const physicalClock = flag('--physical-clock');
const MAX_TICKS = physicalClock ? 66000 : 54000;
const ticks = Number(arg('--ticks') ?? 600);
if (!Number.isInteger(ticks) || ticks < 1 || ticks > MAX_TICKS) throw new Error(`--ticks must be an integer in 1..${MAX_TICKS}`);
const outPath = arg('--out');
if (!outPath) throw new Error('--out <replay.json> is required');
const lineupPath = arg('--lineup');
const useExample = flag('--upstream-example');
if (!useExample && !lineupPath) throw new Error('Pass --lineup <lineup.json> or --upstream-example');
if (Math.random !== seededRandom) throw new Error('Seeded PRNG not installed before engine imports');

// ── Lineup input ────────────────────────────────────────────────────────────
type CatRole = 'GK' | 'DEF' | 'MID' | 'FWD';
interface InPlayer {
  id?: string; key?: string; player_key?: string; source_key?: string;
  name: string; role: CatRole; side?: 'home' | 'away'; slot?: number;
  attributes?: Record<string, number>; provenance?: Record<string, string>;
  touchlines_stats?: PlayerStatsRecord;
}
interface InTeam { key: string; name: string; formation?: string; players: InPlayer[] }
interface Prepared {
  key: string; name: string; formationId: string; formation: Formation;
  roster: RosterPlayer[]; lineup: string[];
  meta: Map<string, { sourceKey: string; name: string; role: CatRole; attributes: Record<string, number>; provenance: Record<string, string> }>;
}

// TimePitch role priors (backend/src/timepitch/simulation/ratings.py ROLE_ATTRIBUTES), used when a key is missing.
const ROLE_PRIOR: Record<CatRole, Record<string, number>> = {
  GK: { passing: .35, shooting: .08, defending: .20, keeping: .75, pace: .35, stamina: .65 },
  DEF: { passing: .50, shooting: .25, defending: .68, keeping: .05, pace: .52, stamina: .70 },
  MID: { passing: .65, shooting: .45, defending: .50, keeping: .05, pace: .60, stamina: .75 },
  FWD: { passing: .55, shooting: .65, defending: .25, keeping: .05, pace: .65, stamina: .65 },
};
const GRF_KEYS: Record<string, string> = { physical_velocity: 'pace', technical_shot: 'shooting', technical_shortpass: 'passing' };
const STRENGTH: Record<CatRole, number> = { GK: 3.5, DEF: 5, MID: 4, FWD: 4.5 };
const POSITION_LABEL: Record<CatRole, string> = { GK: 'GK', DEF: 'Defender', MID: 'Midfielder', FWD: 'Forward' };

function normaliseAttributes(p: InPlayer): { values: Record<string, number>; provenance: Record<string, string> } {
  const values: Record<string, number> = {}, provenance: Record<string, string> = {};
  for (const [k, v] of Object.entries(p.attributes ?? {})) {
    const key = GRF_KEYS[k] ?? k;
    if (typeof v === 'number' && Number.isFinite(v)) { values[key] = v; provenance[key] = p.provenance?.[k] ?? 'catalogue:unspecified'; }
  }
  for (const [k, v] of Object.entries(ROLE_PRIOR[p.role])) if (!(k in values)) { values[k] = v; provenance[k] = 'estimated:role_prior(harness-default)'; }
  return { values, provenance };
}

// Synthetic estimate: TimePitch 0..1 attributes -> TouchLines 0..10 integer stats.
// Scale chosen from the upstream example Premier League squads (most stats 1..8, mean ~3-4.5).
function estimateStats(role: CatRole, a: Record<string, number>): PlayerStatsRecord {
  const s = (v: number) => Math.max(0, Math.min(10, Math.round(v)));
  const gk = role === 'GK';
  return {
    passing: s(a.passing * 10), vision: s(a.passing * 8), finishing: s(a.shooting * 10),
    dribbling: s((a.pace + a.passing) / 2 * 8), speed: s(a.pace * 8), acceleration: s(a.pace * 9),
    tackling: s(a.defending * 9), pressing: s((a.defending + a.stamina) / 2 * 7), stamina: s(a.stamina * 7),
    heading: s((a.defending + a.shooting) / 2 * 8), strength: s(STRENGTH[role]),
    reflex: gk ? s(a.keeping * 8) : 1, jump: gk ? s(a.keeping * 8) : 1,
  };
}

const SLOT_CATEGORY: Record<string, CatRole> = {
  GK: 'GK', CB: 'DEF', LB: 'DEF', RB: 'DEF', LWB: 'DEF', RWB: 'DEF',
  CDM: 'MID', CM: 'MID', CAM: 'MID', LM: 'MID', RM: 'MID', LW: 'FWD', RW: 'FWD', ST: 'FWD',
};

function prepareTeam(team: InTeam, side: 'home' | 'away', formationOverride?: string): Prepared {
  const formationId = formationOverride ?? team.formation ?? '4-4-2';
  const formation = FORMATIONS[formationId];
  if (!formation) throw new Error(`Unsupported formation ${formationId}`);
  if (team.players.length < 11) throw new Error(`${side}: need 11 players, got ${team.players.length}`);
  const xi = [...team.players].sort((x, y) => (x.slot ?? 0) - (y.slot ?? 0)).slice(0, 11);
  const meta: Prepared['meta'] = new Map();
  const roster: RosterPlayer[] = xi.map(p => {
    const sourceKey = p.source_key ?? p.player_key ?? p.key ?? p.id;
    if (!sourceKey) throw new Error(`${side}: player ${p.name} has no key`);
    const id = `${side}:${sourceKey}`;
    const { values, provenance } = normaliseAttributes(p);
    meta.set(id, { sourceKey, name: p.name, role: p.role, attributes: values, provenance });
    return {
      id, name: p.name, age: 27, squadId: team.key, preferredFoot: 'right', positions: [POSITION_LABEL[p.role]],
      stats: p.touchlines_stats ?? estimateStats(p.role, values),
      profile: { summary: 'synthetic-estimate from TimePitch catalogue', archetype: 'synthetic-estimate' },
    };
  });
  // Assign the XI to formation slots by role category, preserving catalogue order; leftovers fill remaining slots.
  const free = new Set(roster.map(r => r.id));
  const lineup: string[] = formation.attacking.map(slot => {
    const want = SLOT_CATEGORY[slot.role] ?? 'MID';
    const hit = roster.find(r => free.has(r.id) && meta.get(r.id)!.role === want);
    if (hit) { free.delete(hit.id); return hit.id; }
    return '';
  });
  for (let i = 0; i < lineup.length; i++) if (!lineup[i]) { const next = [...free][0]!; free.delete(next); lineup[i] = next; }
  return { key: team.key, name: team.name, formationId, formation, roster, lineup, meta };
}

function exampleTeam(squad: { id: string; name: string; players: RosterPlayer[] }, side: 'home' | 'away', formationId: string): Prepared {
  const formation = FORMATIONS[formationId]!;
  const meta: Prepared['meta'] = new Map();
  const roster = squad.players.map(p => ({ ...p, id: `${side}:${p.id}` }));
  for (const p of roster) {
    const pos = p.positions[0] ?? 'Midfielder';
    const role: CatRole = pos === 'GK' ? 'GK' : pos === 'Defender' ? 'DEF' : pos === 'Forward' || pos === 'Attacker' ? 'FWD' : 'MID';
    meta.set(p.id, { sourceKey: p.id.slice(side.length + 1), name: p.name, role, attributes: {}, provenance: { all: 'upstream-example-squad (modern, non-historical)' } });
  }
  return { key: `touchlines-example:${squad.id}`, name: `${squad.name} (TouchLines example squad)`, formationId, formation, roster, lineup: [], meta };
}

function readLineup(path: string): { home: InTeam; away: InTeam; dataset?: string } {
  let doc = JSON.parse(readFileSync(path, 'utf8'));
  if (doc.input && !doc.home) doc = doc.input;
  if (doc.home && doc.away) return { home: doc.home, away: doc.away, dataset: doc.dataset_version };
  if (doc.config && Array.isArray(doc.players)) {
    const team = (side: 'home' | 'away'): InTeam => ({
      key: doc.config[`${side}_key`], name: doc[`${side}_name`] ?? doc.config[`${side}_key`],
      formation: doc.config[`${side}_formation`], players: doc.players.filter((p: InPlayer) => p.side === side),
    });
    return { home: team('home'), away: team('away'), dataset: doc.dataset_version };
  }
  throw new Error('Unrecognised lineup.json: expected {home,away} teams or a GrfInput-like {config,players}');
}

const formationOverride = arg('--formation');
let home: Prepared, away: Prepared, datasetVersion: string, lineupSha: string | null = null, source: string;
if (useExample) {
  home = exampleTeam(exampleHome as never, 'home', formationOverride ?? '4-4-2');
  away = exampleTeam(exampleAway as never, 'away', formationOverride ?? '4-4-2');
  datasetVersion = `touchlines-example_data@${UPSTREAM_COMMIT}`;
  source = 'upstream-example-squads';
} else {
  const raw = readFileSync(lineupPath!);
  lineupSha = createHash('sha256').update(raw).digest('hex');
  const parsed = readLineup(lineupPath!);
  home = prepareTeam(parsed.home, 'home', formationOverride);
  away = prepareTeam(parsed.away, 'away', formationOverride);
  datasetVersion = parsed.dataset ?? 'unknown';
  source = 'timepitch-catalogue-lineup';
}

// ── Engine events (harness-side subscription; engine closure itself has none) ──
const events: Array<Record<string, unknown>> = [];
let tickIndex = 0;
for (const name of ['goalScored', 'shot', 'shotResolved', 'passAttempted', 'passCompleted', 'passFailed', 'tackle', 'interception', 'offsideCalled'] as const) {
  gameBus.on(name, (payload: unknown) => { events.push({ tick: tickIndex, type: name, ...(payload as object) }); });
}

// ── Build state ─────────────────────────────────────────────────────────────
const randomBeforeState = randomCallCount();
let s: GameState = {
  ...createMatchState(home.roster, home.formation, away.roster, away.formation,
    home.lineup.length ? home.lineup : undefined, away.lineup.length ? away.lineup : undefined),
  matchPhase: 'firstHalf', presentationCountdown: 0, testMode: !physicalClock,
};

const starters = { home: s.players.filter(p => p.team === 'A').sort((a, b) => a.slotIndex - b.slotIndex),
  away: s.players.filter(p => p.team === 'B').sort((a, b) => a.slotIndex - b.slotIndex) };
if (starters.home.length !== 11 || starters.away.length !== 11) throw new Error('Expected 11 starters per side');
const slotOf = new Map<number, { side: 'home' | 'away'; slot: number }>();
for (const side of ['home', 'away'] as const) starters[side].forEach((p, i) => slotOf.set(p.id, { side, slot: i }));

const NATIVE: Record<CatRole, string> = { GK: 'GK', DEF: 'CB', MID: 'CM', FWD: 'CF' };
const inputPlayers = (['home', 'away'] as const).flatMap(side => starters[side].map((p, slot) => {
  const team = side === 'home' ? home : away, m = team.meta.get(p.rosterId)!;
  return {
    id: p.rosterId, side, slot, source_key: m.sourceKey, name: m.name, role: m.role, native_role: NATIVE[m.role],
    touchlines_role: p.role, touchlines_engine_id: p.id,
    attributes: m.attributes,
    provenance: { ...m.provenance, touchlines_stats: source === 'upstream-example-squads' ? 'upstream-example-squad' : 'synthetic-estimate:timepitch-attributes->touchlines-stats(harness mapping)' },
    touchlines_stats: (team.roster.find(r => r.id === p.rosterId)!).stats,
  };
}));

// ── Simulation loop ─────────────────────────────────────────────────────────
const r5 = (v: number) => Math.round(v * 1e5) / 1e5;
const gx = (x: number) => r5(x / PITCH_LENGTH * 2 - 1);
const gy = (y: number) => r5((y / PITCH_WIDTH - 0.5) * 0.84);
const MODE: Record<string, number> = { kickoff: 1, goal_kick: 2, offside_fk: 3, corner: 4, throw_in: 5 };
const samples: Array<Record<string, unknown>> = [];
const t0 = Date.now();

function sample(state: GameState, index: number) {
  const byId = new Map(state.players.map(p => [p.id, p]));
  const xy = (side: 'home' | 'away') => starters[side].map(p => { const q = byId.get(p.id) ?? p; return [gx(q.x), gy(q.y)]; });
  const ball = getBallPos(state);
  const free = !state.pass && !state.shot && !state.looseBall;
  const owner = free ? slotOf.get(state.ballHolderId) : undefined;
  const mode = state.setPiece && state.setPiece.countdown > 0 ? (MODE[state.setPiece.type] ?? 9) : 0;
  const extra: Record<string, unknown> = {};
  if (physicalClock) {
    // Match clock in ms for the viewer: 1st half 0.., 2nd half from 45:00; halftime/matchEnd hold the half's clock.
    extra.physics_ms = index * 100;
    extra.match_time_ms = Math.round((state.matchTime + (state.matchPhase === 'secondHalf' || state.matchPhase === 'matchEnd' ? 2700 : 0)) * 1000);
  }
  samples.push({
    index, engine_step: index, ...extra, score: [state.score.A, state.score.B],
    owner_team: owner ? (owner.side === 'home' ? 0 : 1) : -1, owner_slot: owner ? owner.slot : -1,
    game_mode: mode, home_xy: xy('home'), away_xy: xy('away'), ball_xyz: [gx(ball.x), gy(ball.y), 0],
    tl_match_time_s: Math.round(state.matchTime * 100) / 100, tl_match_phase: state.matchPhase,
    tl_ball_state: state.shot ? 'shot' : state.looseBall ? 'loose' : state.pass ? `pass:${state.pass.kind ?? 'ground'}` : 'held',
  });
}

sample(s, 0);
let stopReason = 'ticks_completed';
let measuredTimeScale: number | null = null;
for (tickIndex = 1; tickIndex <= ticks; tickIndex++) {
  const before = s.matchTime;
  s = tickState(s, DT).state;
  if (tickIndex === 1) {
    measuredTimeScale = Math.round((s.matchTime - before) / DT * 1e6) / 1e6;
    if (physicalClock && measuredTimeScale !== 1) throw new Error(`--physical-clock needs the fair bundle: measured TIME_SCALE ${measuredTimeScale}`);
  }
  sample(s, tickIndex);
  if (s.matchPhase === 'matchEnd') { stopReason = 'match_end'; break; }
  if (tickIndex % 10 === 0) {
    if (Date.now() - t0 > WALL_LIMIT_MS) { stopReason = 'watchdog_wall'; break; }
    if (process.memoryUsage().rss > RSS_LIMIT) { stopReason = 'watchdog_rss'; break; }
  }
}

const bundleSha = (() => { try { return createHash('sha256').update(readFileSync(process.argv[1]!)).digest('hex'); } catch { return 'unavailable'; } })();
const record: Record<string, unknown> = {
  schema_version: 'grf-experimental-1',
  engine_version: ENGINE_VERSION,
  synthetic: true,
  synthetic_notice: 'SYNTHETIC: movement generated by TouchLines free play; not historical tracking. Attributes are synthetic estimates from the TimePitch catalogue.',
  input: {
    config: {
      home_key: home.key, away_key: away.key,
      home_players: inputPlayers.filter(p => p.side === 'home').map(p => p.source_key),
      away_players: inputPlayers.filter(p => p.side === 'away').map(p => p.source_key),
      home_formation: home.formationId, away_formation: away.formationId,
      home_tactic: 'balanced', away_tactic: 'balanced', seed: SEED,
    },
    dataset_version: datasetVersion, ratings_version: 'ratings-1',
    home_name: home.name, away_name: away.name, players: inputPlayers, input_hash: lineupSha ?? '',
  },
  native_binary_sha256: bundleSha,
  attribute_readbacks: [],
  observation_interval_ms: 100,
  metres_per_unit: { x: PITCH_LENGTH * 0.9144 / 2, y: PITCH_WIDTH * 0.9144 / 0.84, basis: 'touchlines yards -> metres (harness inverse of gx/gy)' },
  duration_ms: (samples.length - 1) * 100,
  steps_left: 0,
  samples,
  touchlines: {
    upstream: 'https://github.com/brenosss/touchlines', commit: UPSTREAM_COMMIT, licence: 'AGPL-3.0-or-later',
    source, lineup_sha256: lineupSha, dt_real_s: DT, ticks_requested: ticks, ticks_run: samples.length - 1, stop_reason: stopReason,
    time_note: physicalClock
      ? 'physical clock: TIME_SCALE neutralised to 1 at bundle time; 0.1 s per tick = 0.1 s of match clock, stamina and intent timers (see match_time_ms)'
      : 'sample clock = engine real-time (0.1 s per tick); engine match clock runs at TIME_SCALE=18x (see tl_match_time_s)',
    measured_time_scale: measuredTimeScale, physical_clock: physicalClock,
    match_phase: s.matchPhase, test_mode: !physicalClock, prng: 'mulberry32 replacing Math.random before engine import',
    random_calls_before_state: randomBeforeState, random_calls_total: randomCallCount(),
    buffs_note: 'upstream computeBuffedStats applied at construction with seeded Math.random (no seasonLog)',
    wall_ms: Date.now() - t0, peak_rss_bytes_sampled: process.memoryUsage().rss,
    calibration: (globalThis as Record<string, unknown>).__tpCalibration ?? null,
    events,
  },
};
record.trace_hash = createHash('sha256').update(JSON.stringify(record)).digest('hex');
const out = resolve(outPath);
mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, JSON.stringify(record));
console.log(JSON.stringify({ out, stop_reason: stopReason, samples: samples.length, score: s.score, wall_ms: Date.now() - t0, rss: process.memoryUsage().rss, events: events.length, trace_hash: record.trace_hash }));
if (stopReason.startsWith('watchdog')) process.exitCode = 3;
